model = _load(model_name)
wav, sample_rate = torchaudio.load(input_audio)
if wav.shape[0] == 1:
    wav = wav.repeat(2, 1)
with torch.no_grad():
    sources = apply_model(model, wav[None].to(DEVICE), split=True)[0]
stems = {name: source for name, source in zip(model.sources, sources)}
return (
    _save(stems["drums"], sample_rate),
    _save(stems["bass"], sample_rate),
    _save(stems["vocals"], sample_rate),
    _save(stems["other"], sample_rate),
)
